const MISSING = { status: 'rejected', code: 'not_found', reason: 'not in the Member scene' };

/** The id a per-input route is keyed by in KEYED. */
const inputIdOf = (route, input) => {
  const value = input ?? {};
  switch (route) {
    case 'lines/page': return value.section;
    case 'lines/read': return value.key?.sessionId;
    case 'goals/read': return value.goalId;
    case 'goals/display': case 'tasks/query': return value.goalRef?.goalId;
    case 'messages/view': return value.messageId;
    case 'messages/body': return `${value.messageRef?.messageId}:${value.part}`;
    case 'executions/read': return value.runId;
    case 'executions/brief': return value.runRef?.runId;
    case 'queries/read': return value.queryJobId;
    case 'queries/answer': return value.answerId;
    default: return undefined;
  }
};

export const scene = {
  now: "2026-10-23T09:00:01.000Z",
  reply(route, input) {
    if (route in KEYED) return KEYED[route][inputIdOf(route, input)] ?? MISSING;
    return ROUTES[route];
  },
};
